endpoints.truth_yaml:
post:
  operationId: post.workspaces.webhooks
  summary: Create a webhook subscription
  x-verification-status: UNCONFIRMED-AGREE
  x-evidence:
    - PROBE-LOG/20260521-040000-post.workspaces.webhooks-dry-run.json
    - PROBE-LOG/20260520-232433-delete.workspaces.webhooks-happy-path.json
  x-notes: "POST /workspaces/{wId}/webhooks: both specs agree. Dry-run confirmed payload shape. Prior iter14 live evidence confirms path exists (webhook was created+deleted). Webhook name maxLength is 30 (enforced by MCP schema). No fresh live POST due to network outage."
  parameters:
    - {name: workspaceId, in: path, required: true, schema: {type: string}}
  requestBody:
    required: true
    content:
      application/json:
        schema:
          type: object
          required: [name, url, webhookEvent]
          properties:
            name: {type: string, minLength: 2, maxLength: 30}
            url: {type: string, description: HTTPS callback URL}
            webhookEvent: {type: string, description: Event type e.g. NEW_TIME_ENTRY}
            triggerSourceType: {type: string, enum: [WORKSPACE_ID, PROJECT_ID, USER_ID, TAG_ID, TASK_ID, ASSIGNMENT_ID, EXPENSE_ID], default: WORKSPACE_ID}
            triggerSource: {type: array, items: {type: string}, description: Trigger source IDs (defaults to workspace ID)}
            authToken: {type: string, description: Optional HMAC signing secret}
  responses:
    '201':
      description: Webhook created
      content:
        application/json:
          schema:
            type: object
            properties:
              id: {type: string}
              name: {type: string}
              url: {type: string}
              webhookEvent: {type: string}
              triggerSourceType: {type: string}
              triggerSource: {type: array, items: {type: string}}
              workspaceId: {type: string}
              userId: {type: string}
              enabled: {type: boolean}
              deliveryEnabled: {type: boolean}
              planEnabled: {type: boolean}

put:
  operationId: put.workspaces.clients
  summary: Update a client by ID (full replacement)
  x-verification-status: UNCONFIRMED-AGREE
  x-evidence:
    - PROBE-LOG/20260521-040000-put.workspaces.clients-code-analysis.json
    - PROBE-LOG/20260521-001500-delete.workspaces.clients-happy-path.json
  x-notes: "PUT /workspaces/{wId}/clients/{clientId}: both specs agree on PUT. Official uses {id}, ours uses {clientId} — same segment. Prior iter11 GET+DELETE confirmed path is live. MCP uses PutWithQuery (full-replacement body; Clockify requires name field). No fresh PUT live probe due to network outage."
  parameters:
    - {name: workspaceId, in: path, required: true, schema: {type: string}}
    - {name: clientId, in: path, required: true, schema: {type: string}, description: 'Client ID. Also documented as {id} in official spec — same URL segment.'}
    - {name: archive-projects, in: query, schema: {type: boolean}}
    - {name: mark-tasks-as-done, in: query, schema: {type: boolean}}
  requestBody:
    required: true
    content:
      application/json:
        schema:
          type: object
          required: [name]
          properties:
            name: {type: string, description: Required by Clockify validator; omitting clears the name}
            email: {type: string}
            address: {type: string}
            note: {type: string}
            currencyId: {type: string}
            archived: {type: boolean}
            ccEmails: {type: array, items: {type: string}}
  responses:
    '200':
      description: Updated client object
      content:
        application/json:
          schema:
            type: object
            properties:
              id: {type: string}
              name: {type: string}
              archived: {type: boolean}
